import java.util.ArrayList;
import java.util.List;

public class Ex03ChooseSetTrim {

    // 复刻 <choose><when test="type eq 'A'">...<otherwise>
    static String choose(String type) {
        if ("A".equals(type)) {
            return "status = 0";
        }
        if ("B".equals(type)) {
            return "status = 1";
        }
        return "1 = 1";
    }

    // 复刻 <set>：非空才加 SET，并去掉尾部多余逗号
    static class SetTag {
        private final List<String> items = new ArrayList<String>();

        void append(String assignment, boolean cond) {
            if (cond) {
                items.add(assignment);
            }
        }

        String render() {
            if (items.isEmpty()) {
                return "";
            }
            String body = String.join(", ", items);
            body = body.replaceFirst(",\\s*$", "");
            return "SET " + body;
        }
    }

    // 复刻 <trim prefix prefixOverrides suffixOverrides>
    static class TrimTag {
        private final List<String> items = new ArrayList<String>();

        void append(String fragment, boolean cond) {
            if (cond) {
                items.add(fragment);
            }
        }

        String render(String prefix, String prefixOverrides, String suffixOverrides) {
            if (items.isEmpty()) {
                return "";
            }
            String body = String.join(" ", items).trim();
            if (!prefixOverrides.isEmpty()) {
                for (String ov : prefixOverrides.split("\\|")) {
                    String token = ov.trim();
                    if (!token.isEmpty() && body.toUpperCase().startsWith(token.toUpperCase())) {
                        body = body.substring(token.length()).trim();
                        break;
                    }
                }
            }
            if (!suffixOverrides.isEmpty()) {
                for (String ov : suffixOverrides.split("\\|")) {
                    String token = ov.trim();
                    if (!token.isEmpty() && body.toUpperCase().endsWith(token.toUpperCase())) {
                        body = body.substring(0, body.length() - token.length()).trim();
                        break;
                    }
                }
            }
            return (prefix.isEmpty() ? "" : prefix + " ") + body;
        }
    }

    public static void main(String[] args) {
        System.out.println("choose type=A   : " + choose("A"));
        System.out.println("choose type=B   : " + choose("B"));
        System.out.println("choose type=Z   : " + choose("Z"));

        SetTag s1 = new SetTag();
        s1.append("name = ?", true);
        s1.append("age = ?", false);
        s1.append("email = ?", true);
        System.out.println("set render      : " + s1.render());
        System.out.println("set full SQL    : UPDATE t_user " + s1.render() + " WHERE id = ?");

        SetTag s2 = new SetTag();
        s2.append("name = ?", false);
        System.out.println("set empty       : <no SET clause>");
        System.out.println("set empty ok    : " + (!s2.render().isEmpty()));

        TrimTag t1 = new TrimTag();
        t1.append("AND name = ?", true);
        t1.append("AND age > ?", true);
        t1.append("AND phone = ?", false);
        System.out.println("trim where      : " + t1.render("WHERE", "AND |OR ", ""));

        TrimTag t2 = new TrimTag();
        t2.append("name = ?,", true);
        t2.append("age = ?,", true);
        t2.append("email = ?,", false);
        System.out.println("trim set        : " + t2.render("SET", "", ","));
    }
}
